PREFIX : <https://w3id.org/rastro/energia#>
SELECT (SUM(?oilC * ?pct / 100) AS ?total) WHERE {
  { SELECT ?c (SUM(?oil) AS ?oilC) WHERE {
      ?p a :WellProduction ; :inConcession ?c ; :oil ?oil .
    } GROUP BY ?c }
  { SELECT ?c (SUM(?pc) AS ?pct) WHERE {
      ?s a :Stake ; :inConcession ?c ; :partner ?co ; :percent ?pc .
      { SELECT DISTINCT ?co WHERE {
          ?co a :Company ; :name ?n .
          FILTER(STRSTARTS(UCASE(STR(?n)), "YPF"))
      } }
    } GROUP BY ?c }
}

PREFIX : <https://w3id.org/rastro/energia#>
SELECT (COUNT(DISTINCT ?w) AS ?n) WHERE {
  ?w a :Well ; :operator ?c .
  ?c :name ?name .
  FILTER(REGEX(?name, "^YPF( |$)", "i"))
}

PREFIX : <https://w3id.org/rastro/energia#>
SELECT ?nombre WHERE {
  {
    SELECT ?c (COUNT(DISTINCT ?v) AS ?n) WHERE {
      ?v a :DetectedVenting ; :inConcession ?c ; :date ?d .
      FILTER(STR(?d) >= "2024-01-01")
    } GROUP BY ?c
  }
  ?c :name ?nombre .
}
ORDER BY DESC(?n)
LIMIT 5

PREFIX : <https://w3id.org/rastro/energia#>
SELECT ?nombre WHERE {
  { SELECT ?c (SUM(?oil) AS ?total) WHERE {
      ?p a :UnconventionalProduction ; :declaredBy ?c ; :oil ?oil .
    } GROUP BY ?c }
  ?c :name ?nombre .
}
ORDER BY DESC(?total)
LIMIT 5

PREFIX : <https://w3id.org/rastro/energia#>
SELECT DISTINCT ?nombre WHERE {
  ?p a :WellProduction ; :declaredBy ?e .
  ?e :lei ?lei ; :name ?nombre .
}
